INSERT INTO stories (id,title,subtitle,theme,material_id,age_band,page_count,style,cover_illus,pages, edu_goals_summary,symbol_ids,source_type,ai_generated,status,published_at) VALUES (2,'温柔的洱海妈妈','洱海守护小绘本','洱海',NULL,'5-6',7,'水彩','','[{"page_no": 1, "type": "cover", "text": "", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}, {"page_no": 2, "type": "content", "text": "清晨的大理，薄雾轻轻笼罩着广阔的洱海\\n\\n小宇和小伙伴们相约，来到洱海边散步游玩", "goal_text": "树立爱护自然、保护洱海生态的意识，培养幼儿爱护家乡环境的良好品质。", "goal_domains": ["社会领域"], "illus": "", "illus_prompt": "清晨薄雾笼罩的洱海边，小宇和小伙伴们开心地散步游玩"}, {"page_no": 3, "type": "content", "text": "澄澈的洱海湖水蓝蓝的，像一块巨大的蓝宝石\\n\\n湖面波光粼粼，温柔地依偎着苍山脚下", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "蓝宝石般的洱海湖水波光粼粼，温柔地依偎在苍山脚下"}, {"page_no": 4, "type": "content", "text": "成群的海鸥在湖面飞舞、嬉戏，自由又欢快\\n\\n湖边的芦苇随风摇摆，开出软软的白绒花", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "成群海鸥在湖面飞舞嬉戏，湖边芦苇随风摇摆开出白绒花"}, {"page_no": 5, "type": "content", "text": "洱海滋养着大理的一草一木，守护着这里的生灵\\n\\n它是大理人最温柔的家乡母亲湖", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "洱海像温柔的妈妈，滋养着岸边的花草树木和小生灵"}, {"page_no": 6, "type": "content", "text": "小宇和小伙伴约定，绝不向湖里扔垃圾、破坏环境\\n\\n每个人都要做洱海的小小守护者", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "小宇和小伙伴们在洱海边拉钩约定，做保护洱海的小小守护者"}, {"page_no": 7, "type": "ending", "text": "夕阳西下，余晖洒在湖面，洱海美得像一幅画卷\\n\\n守护绿水青山，才能留住家乡最美的风景", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}]','[{"domain": "社会领域", "count": 1}]','[]','user',0,'published',NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), subtitle=VALUES(subtitle), age_band=VALUES(age_band), page_count=VALUES(page_count), pages=VALUES(pages), edu_goals_summary=VALUES(edu_goals_summary);
INSERT INTO stories (id,title,subtitle,theme,material_id,age_band,page_count,style,cover_illus,pages, edu_goals_summary,symbol_ids,source_type,ai_generated,status,published_at) VALUES (3,'热闹的白族火把节','火把节安全小绘本','火把节',NULL,'3-4',7,'水彩','','[{"page_no": 1, "type": "cover", "text": "", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}, {"page_no": 2, "type": "content", "text": "夏天的大理格外热闹，一年一度的火把节悄悄到来\\n\\n安安和小伙伴们早早来到广场，等待节日盛会", "goal_text": "了解火把节安全常识，建立幼儿明火危险认知，养成自我保护的好习惯。", "goal_domains": ["健康领域"], "illus": "", "illus_prompt": "夏天热闹的大理广场上，安安和小伙伴们早早来到广场等待火把节"}, {"page_no": 3, "type": "content", "text": "大人们扎好了高高的大火把，整齐又壮观\\n\\n干枯的树枝层层叠叠，静静伫立在广场中央", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "广场中央立着扎好的高高大火把，干枯的树枝层层叠叠，整齐壮观"}, {"page_no": 4, "type": "content", "text": "夜幕降临，大火把被轻轻点亮，红红的火光温暖又明亮\\n\\n火光染红了夜空，也照亮了每个人的笑脸", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "夜幕降临，大火把点亮，红红的火光染红夜空，照亮每个人的笑脸"}, {"page_no": 5, "type": "content", "text": "大家围着火把拍手、唱歌、轻轻跳舞\\n\\n广场上充满了欢声笑语，热闹极了", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "大家围着火把拍手、唱歌、跳舞，广场上充满欢声笑语"}, {"page_no": 6, "type": "content", "text": "大人告诉安安，火把节是祈福的节日，寓意平安健康\\n\\n红红的火把，送来满满的美好祝福", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "大人指着火把给安安讲火把节祈福平安的寓意，火光暖暖的"}, {"page_no": 7, "type": "ending", "text": "小朋友要牢记安全，远远观看火把，不触碰明火\\n\\n欢乐过节，平安长大", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}]','[{"domain": "健康领域", "count": 1}]','[]','user',0,'published',NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), subtitle=VALUES(subtitle), age_band=VALUES(age_band), page_count=VALUES(page_count), pages=VALUES(pages), edu_goals_summary=VALUES(edu_goals_summary);
INSERT INTO stories (id,title,subtitle,theme,material_id,age_band,page_count,style,cover_illus,pages, edu_goals_summary,symbol_ids,source_type,ai_generated,status,published_at) VALUES (4,'醇香白族三道茶','白族三道茶小绘本','三道茶',NULL,'4-5',7,'水彩','','[{"page_no": 1, "type": "cover", "text": "", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}, {"page_no": 2, "type": "content", "text": "周末的大理小院清风徐徐，邻居阿叔正在准备特色三道茶\\n\\n朵朵路过小院，被淡淡的茶香深深吸引", "goal_text": "能够大胆描述三道茶的味道与饮用礼仪，提升幼儿口语表达与感知描述能力。", "goal_domains": ["语言领域"], "illus": "", "illus_prompt": "清风拂过的大理小院里，阿叔正在准备三道茶，朵朵被茶香吸引走进小院"}, {"page_no": 3, "type": "content", "text": "阿叔邀请朵朵品尝第一道苦茶，轻轻烘烤的茶叶香气十足\\n\\n茶汤清苦爽口，是三道茶独特的开端", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "阿叔为朵朵递上第一道苦茶，茶汤冒着热气，朵朵小心地品尝"}, {"page_no": 4, "type": "content", "text": "第二道是甜甜的甜茶，阿叔加入了乳扇、核桃和冰糖\\n\\n温热的茶水入口香甜，暖到了心底", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "阿叔往茶碗里加入乳扇、核桃和冰糖，朵朵捧着香甜的甜茶"}, {"page_no": 5, "type": "content", "text": "最后一道是回味茶，搭配少许特色配料，口感丰富特别\\n\\n一口喝下，嘴里香香的，久久都有味道", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "朵朵细细品味第三道回味茶，茶碗里配料丰富，茶香四溢"}, {"page_no": 6, "type": "content", "text": "阿叔告诉朵朵，三道茶寓意先苦后甜，是白族人的生活智慧\\n\\n认真付出，就会收获甜甜的美好", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "小院茶桌前，阿叔笑着给朵朵讲三道茶先苦后甜的道理"}, {"page_no": 7, "type": "ending", "text": "待客泡三道茶，是白族最真诚的祝福\\n\\n朵朵学会了品茶礼仪，做礼貌又温柔的小朋友", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}]','[{"domain": "语言领域", "count": 1}]','[]','user',0,'published',NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), subtitle=VALUES(subtitle), age_band=VALUES(age_band), page_count=VALUES(page_count), pages=VALUES(pages), edu_goals_summary=VALUES(edu_goals_summary);
INSERT INTO stories (id,title,subtitle,theme,material_id,age_band,page_count,style,cover_illus,pages, edu_goals_summary,symbol_ids,source_type,ai_generated,status,published_at) VALUES (5,'欢乐三月街','三月街赶集小绘本','三月街',NULL,'4-5',7,'水彩','','[{"page_no": 1, "type": "cover", "text": "", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}, {"page_no": 2, "type": "content", "text": "春暖花开的三月，大理最热闹的三月街开市啦\\n\\n乐乐跟着表姐，开开心心逛民俗大街", "goal_text": "观察三月街多样的物产、手作与民俗活动，丰富幼儿对生活与民俗的认知经验。", "goal_domains": ["科学领域"], "illus": "", "illus_prompt": "春暖花开的三月街开市，乐乐跟着表姐开开心心逛民俗大街"}, {"page_no": 3, "type": "content", "text": "长长的街道摆满了各式各样的好物，琳琅满目\\n\\n香香的特色小吃、精致的手工饰品，看得人眼花缭乱", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "三月街街道两旁摆满特色小吃和精致的手工饰品，琳琅满目"}, {"page_no": 4, "type": "content", "text": "街上的白族叔叔阿姨穿着漂亮的民族服饰\\n\\n大家热情叫卖、友好交流，氛围温暖又热闹", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "穿着漂亮白族服饰的叔叔阿姨热情叫卖，街上氛围温暖热闹"}, {"page_no": 5, "type": "content", "text": "广场上还有精彩的歌舞表演，歌声清脆，舞姿优美\\n\\n乐乐停下脚步，认真欣赏精彩的民俗节目", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "广场上白族歌舞表演精彩，乐乐停下脚步认真欣赏"}, {"page_no": 6, "type": "content", "text": "表姐告诉乐乐，三月街是白族千年的传统盛会\\n\\n人们在这里赶集、交友、祈福，代代相传", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "表姐微笑着给乐乐讲三月街千年的传统盛会"}, {"page_no": 7, "type": "ending", "text": "乐乐挑选了小礼物，准备分享给幼儿园的好朋友\\n\\n热闹的三月街，藏着大理最温暖的烟火气息", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}]','[{"domain": "科学领域", "count": 1}]','[]','user',0,'published',NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), subtitle=VALUES(subtitle), age_band=VALUES(age_band), page_count=VALUES(page_count), pages=VALUES(pages), edu_goals_summary=VALUES(edu_goals_summary);
INSERT INTO stories (id,title,subtitle,theme,material_id,age_band,page_count,style,cover_illus,pages, edu_goals_summary,symbol_ids,source_type,ai_generated,status,published_at) VALUES (6,'屋顶的吉祥瓦猫','瓦猫守护小绘本','瓦猫',NULL,'5-6',8,'水彩','','[{"page_no": 1, "type": "cover", "text": "", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}, {"page_no": 2, "type": "content", "text": "大理白族的老院房顶，总会蹲着一只只可爱的瓦猫\\n\\n林夕跟着陶艺师傅，探秘瓦猫的小秘密", "goal_text": "欣赏瓦猫陶艺造型之美，感受传统民间陶艺的独特魅力，提升幼儿审美感知力。", "goal_domains": ["艺术领域"], "illus": "", "illus_prompt": "白族老院的房顶上蹲着可爱的瓦猫，林夕跟着陶艺师傅抬头探秘"}, {"page_no": 3, "type": "content", "text": "瓦猫是用纯净的陶土手工揉捏、塑形制作而成的\\n\\n经过高温烧制、晾晒，变得坚固又精致", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "陶艺师傅用陶土揉捏塑形，手工制作瓦猫"}, {"page_no": 4, "type": "content", "text": "瓦猫圆脸蛋、大嘴巴，模样憨憨的、十分可爱\\n\\n每一只瓦猫都是匠人亲手制作，造型独一无二", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "一只只圆脸蛋、大嘴巴的瓦猫摆在一起，憨态可掬，造型各不相同"}, {"page_no": 5, "type": "content", "text": "师傅告诉林夕，瓦猫是白族的吉祥守护神\\n\\n它驻守屋顶，守护小院安宁，带来平安福气", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "陶艺师傅捧着瓦猫，给林夕讲瓦猫是白族吉祥守护神的故事"}, {"page_no": 6, "type": "content", "text": "风吹日晒、四季轮回，瓦猫默默守护着家家户户\\n\\n它不张扬，却承载着白族人美好的心愿", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "风吹日晒中，瓦猫静静蹲在屋顶，守护着白族小院"}, {"page_no": 7, "type": "content", "text": "林夕读懂了瓦猫的故事，爱上了这门传统陶艺\\n\\n小小瓦猫，是大理最珍贵的民俗小宝藏", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "林夕抱着瓦猫爱不释手，脸上露出喜爱与珍惜的笑容"}, {"page_no": 8, "type": "ending", "text": "传统手艺温暖又治愈，我们要好好传承和珍惜\\n\\n让吉祥的瓦猫，一直守护美丽的大理\\n\\n|（注：部分内容可能由 AI 生成）", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}]','[{"domain": "艺术领域", "count": 1}]','[]','user',0,'published',NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), subtitle=VALUES(subtitle), age_band=VALUES(age_band), page_count=VALUES(page_count), pages=VALUES(pages), edu_goals_summary=VALUES(edu_goals_summary);
INSERT INTO stories (id,title,subtitle,theme,material_id,age_band,page_count,style,cover_illus,pages, edu_goals_summary,symbol_ids,source_type,ai_generated,status,published_at) VALUES (7,'神奇的白族扎染','白族扎染小绘本','扎染',NULL,'3-4',8,'水彩','','[{"page_no": 1, "type": "cover", "text": "", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}, {"page_no": 2, "type": "content", "text": "阳光洒进幼儿园的美工室\\n\\n老师拿出软软的白布，邀请小朋友们做扎染\\n\\n小白睁大眼睛，好奇地看着干干净净的白色布料", "goal_text": "感受白族扎染蓝白花纹的独特美感，萌发幼儿对民间手工艺术的创作与欣赏兴趣。", "goal_domains": ["艺术领域"], "illus": "", "illus_prompt": "阳光洒满的美工室里，老师拿出软软的白布，小白睁大眼睛好奇地看着白色布料"}, {"page_no": 3, "type": "content", "text": "老师告诉大家，蓝色的染料来自天然的板蓝根叶子\\n\\n这是大自然送给白族小朋友的彩色礼物", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "老师举起板蓝根叶子，向小朋友们讲解天然的蓝色染料"}, {"page_no": 4, "type": "content", "text": "小白学着小伙伴的样子，把白布轻轻捏起来\\n\\n他用彩色皮筋，把布的小角紧紧扎了起来", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "小白用彩色皮筋把白布的小角紧紧扎起来，认真学做扎染"}, {"page_no": 5, "type": "content", "text": "扎好的白布被轻轻放进蓝色染水里\\n\\n布料慢慢吸水，一点点染上温柔的蓝色", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "扎好的白布被轻轻放进蓝色染水里，布料慢慢染上蓝色"}, {"page_no": 6, "type": "content", "text": "等待片刻后，小白小心解开皮筋\\n\\n白白的布料变出了好看的白花，太惊喜啦", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "小白小心解开皮筋，惊喜地看着白布上变出好看的白花"}, {"page_no": 7, "type": "content", "text": "每个小朋友的扎染花纹都不一样，各有各的可爱\\n\\n天然的植物染色，温柔又保护大自然", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": "小朋友们展示花纹各不相同的扎染蓝白花布，每一块都独一无二"}, {"page_no": 8, "type": "ending", "text": "小白举着自己的蓝白花布，开心地和小伙伴展示作品\\n\\n原来传统手艺，这么有趣又好看", "goal_text": "", "goal_domains": [], "illus": "", "illus_prompt": ""}]','[{"domain": "艺术领域", "count": 1}]','[]','user',0,'published',NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), subtitle=VALUES(subtitle), age_band=VALUES(age_band), page_count=VALUES(page_count), pages=VALUES(pages), edu_goals_summary=VALUES(edu_goals_summary);
